### 3.4 Key test code

The reference implementation used for differential testing:

```go
// bruteIdom computes immediate dominators with a classic set-based dataflow
// fixpoint. It is deliberately independent from the production code.
func bruteIdom(g *Graph, root int) []int {
	n := g.n
	reach := make([]bool, n)
	reach[root] = true
	stack := []int{root}
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, w := range g.Successors(v) {
			if !reach[w] {
				reach[w] = true
				stack = append(stack, w)
			}
		}
	}
	dom := make([][]bool, n)
	for v := 0; v < n; v++ {
		dom[v] = make([]bool, n)
	}
	for v := 0; v < n; v++ {
		if !reach[v] {
			continue
		}
		if v == root {
			dom[v][root] = true
			continue
		}
		for d := 0; d < n; d++ {
			dom[v][d] = true
		}
		dom[v][v] = true
	}
	for changed := true; changed; {
		changed = false
		for v := 0; v < n; v++ {
			if !reach[v] || v == root {
				continue
			}
			any := false
			newset := make([]bool, n)
			for d := 0; d < n; d++ {
				newset[d] = true
			}
			for _, p := range g.Predecessors(v) {
				if !reach[p] {
					continue
				}
				any = true
				for d := 0; d < n; d++ {
					newset[d] = newset[d] && dom[p][d]
				}
			}
			if !any {
				continue
			}
			newset[v] = true
			same := true
			for d := 0; d < n; d++ {
				if newset[d] != dom[v][d] {
					same = false
					break
				}
			}
			if !same {
				dom[v] = newset
				changed = true
			}
		}
	}
	idom := make([]int, n)
	for i := range idom {
		idom[i] = -1
	}
	idom[root] = root
	for v := 0; v < n; v++ {
		if !reach[v] || v == root {
			continue
		}
		best, bestSize := -1, -1
		for d := 0; d < n; d++ {
			if d == v || !dom[v][d] {
				continue
			}
			size := 0
			for x := 0; x < n; x++ {
				if dom[d][x] {
					size++
				}
			}
			if size > bestSize {
				bestSize, best = size, d
			}
		}
		idom[v] = best
	}
	return idom
}
